edits.oldText:
export function shouldRetry(status: number) {
  return status === 429 || status >= 500;
}

edits.newText:
export function shouldRetry(method: string, status: number) {
  if (status === 429) {
    return method === "GET" || method === "HEAD";
  }
  return status >= 500;
}

edits.oldText:
export async function request(method: "GET" | "POST", status: number) {
  if (shouldRetry(status)) {
    return "retry";
  }
  return `${method}:done`;
}

edits.newText:
export async function request(method: "GET" | "POST" | "HEAD", status: number) {
  if (shouldRetry(method, status)) {
    return "retry";
  }
  return `${method}:done`;
}
